-- 214: Original BrillaPrep WASSCE BrillaPrep transitional Sculpture beta content blueprint questions, part 2.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_214_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_214_guard;
INSERT INTO _migration_214_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_005' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_1' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why should a comparison of Greek athletic sculpture and West African ceremonial sculpture begin with context as well as appearance?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Both traditions can be judged accurately by anatomical realism alone","B. A shared use of the human figure proves that both objects had the same purpose","C. Their forms respond to different patrons, beliefs, functions, materials and viewing situations","D. The older object must have influenced the newer one even without contact evidence"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Context prevents false equivalence. Comparing patronage, belief, function, material, setting and visual choices reveals both meaningful similarities and culturally specific differences. Therefore the correct answer is C: Their forms respond to different patrons, beliefs, functions, materials and viewing situations.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_1' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_005' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_214_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_006' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_2' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is an alloy used in sculpture?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A mixture of clay and grog prepared for terracotta modelling","B. A resin casting filled with bronze-coloured powder on its surface","C. A pure metal that has been polished until two colours appear","D. A metallic material formed by combining two or more elements, with at least one being a metal"]' AND q.correct_answer IS 'D' AND q.explanation IS 'An alloy combines elements to obtain useful metallic properties. Brass, for example, combines copper and zinc; bronze commonly combines copper and tin, though exact compositions vary. Therefore the correct answer is D: A metallic material formed by combining two or more elements, with at least one being a metal.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_006' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_214_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_007' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_2' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which statement best defines high relief sculpture?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Lines are incised below the surface without any raised modelling","B. The figure is completely detached and can be viewed equally from every side","C. Forms rise only slightly and preserve a shallow, nearly flat picture plane","D. Forms project strongly from the background and may be undercut, while remaining attached to it"]' AND q.correct_answer IS 'D' AND q.explanation IS 'High relief creates strong projection, shadow and spatial overlap. Parts may approach three-dimensional form or be undercut, but the composition remains physically connected to its background plane. Therefore the correct answer is D: Forms project strongly from the background and may be undercut, while remaining attached to it.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_007' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_214_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_008' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_2' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which control is most appropriate when dry sanding a material that may release fine mineral dust?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Sweep the dry dust after each piece while other users remain nearby","B. Use extraction or wet suppression with correctly selected respiratory protection","C. Use general room ventilation alone while sanding close to the face","D. Wear a loose cloth covering while compressed air clears the bench"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Fine mineral dust can remain airborne and reach deep into the lungs. Control begins at source through extraction or wet methods, supported by suitable ventilation, housekeeping and respiratory protection. Therefore the correct answer is B: Use extraction or wet suppression with correctly selected respiratory protection.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_008' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_005', 'topic_was_sculpture_b004_1', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'Why should a comparison of Greek athletic sculpture and West African ceremonial sculpture begin with context as well as appearance?', 'multiple_choice', NULL, '["A. Both traditions can be judged accurately by anatomical realism alone","B. A shared use of the human figure proves that both objects had the same purpose","C. Their forms respond to different patrons, beliefs, functions, materials and viewing situations","D. The older object must have influenced the newer one even without contact evidence"]', 'C', 'Context prevents false equivalence. Comparing patronage, belief, function, material, setting and visual choices reveals both meaningful similarities and culturally specific differences. Therefore the correct answer is C: Their forms respond to different patrons, beliefs, functions, materials and viewing situations.', 'medium', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_1', 'Explain', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_006', 'topic_was_sculpture_b004_2', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'What is an alloy used in sculpture?', 'multiple_choice', NULL, '["A. A mixture of clay and grog prepared for terracotta modelling","B. A resin casting filled with bronze-coloured powder on its surface","C. A pure metal that has been polished until two colours appear","D. A metallic material formed by combining two or more elements, with at least one being a metal"]', 'D', 'An alloy combines elements to obtain useful metallic properties. Brass, for example, combines copper and zinc; bronze commonly combines copper and tin, though exact compositions vary. Therefore the correct answer is D: A metallic material formed by combining two or more elements, with at least one being a metal.', 'hard', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_2', 'Identify', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_007', 'topic_was_sculpture_b004_2', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'Which statement best defines high relief sculpture?', 'multiple_choice', NULL, '["A. Lines are incised below the surface without any raised modelling","B. The figure is completely detached and can be viewed equally from every side","C. Forms rise only slightly and preserve a shallow, nearly flat picture plane","D. Forms project strongly from the background and may be undercut, while remaining attached to it"]', 'D', 'High relief creates strong projection, shadow and spatial overlap. Parts may approach three-dimensional form or be undercut, but the composition remains physically connected to its background plane. Therefore the correct answer is D: Forms project strongly from the background and may be undercut, while remaining attached to it.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_2', 'Identify', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_008', 'topic_was_sculpture_b004_2', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'Which control is most appropriate when dry sanding a material that may release fine mineral dust?', 'multiple_choice', NULL, '["A. Sweep the dry dust after each piece while other users remain nearby","B. Use extraction or wet suppression with correctly selected respiratory protection","C. Use general room ventilation alone while sanding close to the face","D. Wear a loose cloth covering while compressed air clears the bench"]', 'B', 'Fine mineral dust can remain airborne and reach deep into the lungs. Control begins at source through extraction or wet methods, supported by suitable ventilation, housekeeping and respiratory protection. Therefore the correct answer is B: Use extraction or wet suppression with correctly selected respiratory protection.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_2', 'Identify', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-visual-arts-beta-004', 'automated_beta', 'beta', 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.', 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf', 0, 1 FROM questions WHERE id IN ('q_was_sculpture_b004_005', 'q_was_sculpture_b004_006', 'q_was_sculpture_b004_007', 'q_was_sculpture_b004_008');
DELETE FROM _migration_214_guard;
INSERT INTO _migration_214_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions WHERE id IN ('q_was_sculpture_b004_005', 'q_was_sculpture_b004_006', 'q_was_sculpture_b004_007', 'q_was_sculpture_b004_008')) = 4 AND (SELECT COUNT(*) FROM question_content_releases r WHERE r.question_id IN ('q_was_sculpture_b004_005', 'q_was_sculpture_b004_006', 'q_was_sculpture_b004_007', 'q_was_sculpture_b004_008') AND r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 4 THEN 1 ELSE 0 END;
